display.text:
import { useMemo, useState } from "react";

import { isUnderserved, opportunityScore } from "../../lib/odi";
import { useStudio } from "../../state/StudioContext";

export function DirectCapture() {
  const { canvas, addOutcome } = useStudio();
  const jobs = canvas?.jobs ?? [];

  const [jobId, setJobId] = useState<string | null>(null);
  const [statement, setStatement] = useState("");
  const [importance, setImportance] = useState(8.5);
  const [satisfaction, setSatisfaction] = useState(3.5);
  const [busy, setBusy] = useState(false);

  const activeJobId = jobId ?? jobs[0]?.id ?? "";

  const calcOpp = useMemo(
    () => opportunityScore(importance, satisfaction),
    [importance, satisfaction],
  );

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!statement.trim() || !activeJobId || busy) {
      return;
    }
    setBusy(true);
    try {
      await addOutcome({
        job_id: activeJobId,
        statement: statement.trim(),
        importance,
        satisfaction,
      });
      setStatement("");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <h2 className="section-title">Direct Capture: Jobs &amp; Outcomes</h2>
      <p className="caption">
        Prefer direct entry over conversational typing? Add artifacts directly to the MCP
        repository.
      </p>

      <form onSubmit={submit}>
        <div className="studio-field">
          <label htmlFor="dc-job">Select Job</label>
          <select
            id="dc-job"
            className="studio-select"
            value={activeJobId}
            onChange={(event) => setJobId(event.target.value)}
          >
            {jobs.map((job) => (
              <option key={job.id} value={job.id}>
                {job.id}: {job.name ?? ""}
              </option>
            ))}
          </select>
        </div>

        <div className="studio-field">
          <label htmlFor="dc-statement">Desired Outcome Statement</label>
          <input
            id="dc-statement"
            className="studio-input"
            placeholder="Minimize the time it takes to..."
            value={statement}
            onChange={(event) => setStatement(event.target.value)}
          />
          <p className="caption" style={{ marginTop: 4 }}>
            Format: [Direction] + [Unit of Measure] + [Object of Control] + [Contextual Clarifier]
          </p>
        </div>

        <div className="studio-form-grid">
          <div className="studio-field">
            <label htmlFor="dc-importance">Importance Score (1-10): {importance.toFixed(1)}</label>
            <input
              id="dc-importance"
              type="range"
              min={1}
              max={10}
              step={0.1}
              value={importance}
              onChange={(event) => setImportance(Number(event.target.value))}
            />
          </div>
          <div className="studio-field">
            <label htmlFor="dc-satisfaction">
              Current Satisfaction (1-10): {satisfaction.toFixed(1)}
            </label>
            <input
              id="dc-satisfaction"
              type="range"
              min={1}
              max={10}
              step={0.1}
              value={satisfaction}
              onChange={(event) => setSatisfaction(Number(event.target.value))}
            />
          </div>
        </div>

        <p className="toast toast--info" role="status" style={{ marginBottom: 12 }}>
          📊 <b>Calculated Opportunity Score</b>: <code>{calcOpp.toFixed(2)}</code> (
          {isUnderserved(calcOpp) ? "🔥 Underserved" : "Appropriately Served"})
        </p>

        <button type="submit" className="studio-button" disabled={busy || !statement.trim()}>
          Record Desired Outcome
        </button>
      </form>
    </section>
  );
}

/* eslint-disable react-refresh/only-export-components -- context module intentionally exports the hook and constants alongside the provider */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";

import {
  addOutcome as apiAddOutcome,
  addStep as apiAddStep,
  fetchCanvas,
  fetchConfig,
  healthLlm,
  healthMcp,
  streamChat,
} from "../api/studioApi";
import type { RawSseEvent } from "../api/sse";
import type {
  AddOutcomePayload,
  AddStepPayload,
  CanvasData,
  ChatMessage,
  StudioConfig,
} from "../types";

const SETTINGS_KEY = "studio.settings";
const CANVAS_KEY = "studio.canvas";

export const WELCOME_MESSAGE =
  "Welcome to **The Living Studio**. We have eliminated backlogs and Jira spreadsheets.\n\n" +
  "You are looking at a living map of human progress. Tell me what your customers are struggling with, " +
  "or click on any outcome on the canvas to inspect its causality.";

export const EMPTY_CONFIG: StudioConfig = {
  base_url: "http://localhost:8001/v1",
  api_key: "local",
  model_name: "local-tools-model",
  mcp_url: "http://localhost:8000/mcp",
};

export type ToastKind = "success" | "error" | "info";

export interface Toast {
  id: number;
  kind: ToastKind;
  message: string;
}

export interface ToolActivity {
  name: string;
  status: string;
  preview?: string;
}

export interface StudioContextValue {
  settings: StudioConfig;
  saveSettings: (config: StudioConfig) => void;
  canvas: CanvasData | null;
  canvasLoading: boolean;
  canvasCached: boolean;
  refreshCanvas: () => Promise<void>;
  llmHealth: { healthy: boolean | null; message: string };
  mcpReachable: boolean;
  messages: ChatMessage[];
  streaming: boolean;
  thinkingPhase: string | null;
  toolActivity: ToolActivity[];
  sendMessage: (text: string) => Promise<void>;
  clearChat: () => void;
  addStep: (payload: Omit<AddStepPayload, "mcp_url">) => Promise<void>;
  addOutcome: (payload: Omit<AddOutcomePayload, "mcp_url">) => Promise<void>;
  pendingSimOutcome: string | null;
  requestSimulate: (outcomeId: string) => void;
  clearPendingSimOutcome: () => void;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  toasts: Toast[];
  pushToast: (kind: ToastKind, message: string) => void;
  dismissToast: (id: number) => void;
}

const StudioContext = createContext<StudioContextValue | null>(null);

function loadSettings(): StudioConfig {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      return { ...EMPTY_CONFIG, ...(JSON.parse(raw) as Partial<StudioConfig>) };
    }
  } catch {
    /* ignore malformed cache */
  }
  return EMPTY_CONFIG;
}

function loadCanvasCache(): CanvasData | null {
  try {
    const raw = localStorage.getItem(CANVAS_KEY);
    if (raw) {
      return JSON.parse(raw) as CanvasData;
    }
  } catch {
    /* ignore malformed cache */
  }
  return null;
}

export function StudioProvider({ children }: { children: ReactNode }) {
  const [settings, setSettings] = useState<StudioConfig>(loadSettings);
  const [canvas, setCanvas] = useState<CanvasData | null>(loadCanvasCache);
  const [canvasLoading, setCanvasLoading] = useState(false);
  const [canvasCached, setCanvasCached] = useState(() => loadCanvasCache() !== null);
  const [llmHealth, setLlmHealth] = useState<{ healthy: boolean | null; message: string }>({
    healthy: null,
    message: "Health not checked yet.",
  });
  const [mcpReachable, setMcpReachable] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: "assistant", content: WELCOME_MESSAGE },
  ]);
  const [streaming, setStreaming] = useState(false);
  const [thinkingPhase, setThinkingPhase] = useState<string | null>(null);
  const [toolActivity, setToolActivity] = useState<ToolActivity[]>([]);
  const [pendingSimOutcome, setPendingSimOutcome] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("landscape");
  const [toasts, setToasts] = useState<Toast[]>([]);
  const toastId = useRef(0);
  const abortRef = useRef<AbortController | null>(null);

  const pushToast = useCallback((kind: ToastKind, message: string) => {
    const id = (toastId.current += 1);
    setToasts((prev) => [...prev, { id, kind, message }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((toast) => toast.id !== id));
    }, 6000);
  }, []);

  const dismissToast = useCallback((id: number) => {
    setToasts((prev) => prev.filter((toast) => toast.id !== id));
  }, []);

  const saveSettings = useCallback((config: StudioConfig) => {
    setSettings(config);
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(config));
    } catch {
      /* storage unavailable */
    }
  }, []);

  const refreshCanvas = useCallback(async () => {
    setCanvasLoading(true);
    try {
      const data = await fetchCanvas(settings.mcp_url);
      setCanvas(data);
      setCanvasCached(false);
      try {
        localStorage.setItem(CANVAS_KEY, JSON.stringify(data));
      } catch {
        /* storage unavailable */
      }
    } catch (error) {
      pushToast("error", `Canvas sync failed: ${(error as Error).message}`);
    } finally {
      setCanvasLoading(false);
    }
  }, [settings.mcp_url, pushToast]);

  const addStep = useCallback(
    async (payload: Omit<AddStepPayload, "mcp_url">) => {
      try {
        await apiAddStep({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Step added to Job Map!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error adding step: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const addOutcome = useCallback(
    async (payload: Omit<AddOutcomePayload, "mcp_url">) => {
      try {
        await apiAddOutcome({ ...payload, mcp_url: settings.mcp_url });
        pushToast("success", "Outcome captured successfully!");
        await refreshCanvas();
      } catch (error) {
        pushToast("error", `Error capturing outcome: ${(error as Error).message}`);
      }
    },
    [settings.mcp_url, pushToast, refreshCanvas],
  );

  const clearPendingSimOutcome = useCallback(() => setPendingSimOutcome(null), []);

  const requestSimulate = useCallback((outcomeId: string) => {
    setPendingSimOutcome(outcomeId);
    setActiveTab("impact");
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || streaming) {
        return;
      }

      const history: ChatMessage[] = [...messages, { role: "user", content: trimmed }];
      setMessages([...history, { role: "assistant", content: "" }]);
      setStreaming(true);
      setThinkingPhase("health_check");
      setToolActivity([]);

      const controller = new AbortController();
      abortRef.current = controller;

      let content = "";

      const handleEvent = (event: RawSseEvent) => {
        switch (event.event) {
          case "status":
            setThinkingPhase(String(event.data.phase ?? ""));
            break;
          case "delta": {
            content += String(event.data.text ?? "");
            setMessages((prev) => {
              const next = [...prev];
              next[next.length - 1] = { role: "assistant", content };
              return next;
            });
            break;
          }
          case "tool":
            setToolActivity((prev) => [
              ...prev,
              {
                name: String(event.data.name ?? ""),
                status: String(event.data.status ?? ""),
                preview: event.data.preview ? String(event.data.preview) : undefined,
              },
            ]);
            break;
          case "message":
            content = String(event.data.content ?? content);
            setMessages((prev) => {
              const next = [...prev];
              next[next.length - 1] = { role: "assistant", content };
              return next;
            });
            break;
          case "canvas_dirty":
            void refreshCanvas();
            break;
          case "error":
            pushToast("error", String(event.data.message ?? "Unknown chat error"));
            break;
          default:
            break;
        }
      };

      try {
        await streamChat(
          {
            base_url: settings.base_url,
            api_key: settings.api_key,
            model: settings.model_name,
            mcp_url: settings.mcp_url,
            messages: history,
          },
          handleEvent,
          controller.signal,
        );
      } catch (error) {
        if ((error as Error).name !== "AbortError") {
          pushToast("error", `Error during assistant completion: ${(error as Error).message}`);
          setMessages((prev) => {
            const next = [...prev];
            if (next.length && next[next.length - 1].content === "") {
              next.pop();
            }
            return next;
          });
        }
      } finally {
        setStreaming(false);
        setThinkingPhase(null);
        abortRef.current = null;
      }
    },
    [messages, streaming, settings, refreshCanvas, pushToast],
  );

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    setMessages([{ role: "assistant", content: WELCOME_MESSAGE }]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled && localStorage.getItem(SETTINGS_KEY) === null) {
          saveSettings(defaults);
        }
      } catch {
        /* sidecar not reachable; keep local fallback defaults */
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      setActiveTab,
      toasts,
      pushToast,
      dismissToast,
    }),
    [
      settings,
      saveSettings,
      canvas,
      canvasLoading,
      canvasCached,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      clearChat,
      addStep,
      addOutcome,
      pendingSimOutcome,
      requestSimulate,
      clearPendingSimOutcome,
      activeTab,
      toasts,
      pushToast,
      dismissToast,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

"""Conversational helper with offline fallbacks and a streaming tool loop.

Ported 1:1 from the Streamlit Living Studio app, upgraded to stream over SSE.
"""

from __future__ import annotations

import json
from collections.abc import AsyncIterator
from typing import Any

from fastmcp import Client as McpClient
from openai import AsyncOpenAI

from local_server.studio.probes import check_llm_health
from local_server.studio.schemas import ChatRequest

SYSTEM_PROMPT = """You are Steve Jobs and an elite Outcome-Driven Innovation (ODI) strategist assisting a Product Manager in The Living Studio.
Your mission is to eliminate backlog paper-pushing and help the PM think exclusively in human intent, customer friction, and measurable outcomes.
Key principles:
1. Always start with the Job-to-be-Done (JTBD): "What is the core functional human job?"
2. Uncover Desired Outcomes using the strict ODI format: [Direction] + [Unit of Measure] + [Object of Control] + [Contextual Clarifier]. (e.g. "Minimize the time it takes to propagate secrets across environments").
3. Opportunity Score = Importance + max(Importance - Satisfaction, 0). Scores > 10 represent breakthrough underserved market opportunities.
4. When asked to add or query Jobs, Steps, or Outcomes, ALWAYS invoke the corresponding tools.
5. Embody clarity, focus, and causality. Strip away corporate jargon."""


def offline_fallback(user_input: str) -> str:
    """Intelligent grounded fallback when no LLM backend is reachable."""
    lower_inp = user_input.lower()
    if "guideline" in lower_inp or "framework" in lower_inp or "stage" in lower_inp:
        return (
            "### 📖 Outcome-Driven Innovation (ODI) Process Guidelines\n\n"
            "1. **Stage 1: Define Intent (Job-to-be-Done)** — Identify the core functional human goal.\n"
            "2. **Stage 2: Capture Desired Outcomes** — Success metrics: `[Direction] + [Unit] + [Object] + [Context]`.\n"
            "3. **Stage 3: Opportunity Scoring** — `Importance + max(Importance - Satisfaction, 0)`. Focus on scores > 10.\n"
            "4. **Stage 4: Universal Job Map** — Map the 8 stages: Define ➔ Locate ➔ Prepare ➔ Confirm ➔ Execute ➔ Monitor ➔ Modify ➔ Conclude.\n\n"
            "*(Connected in Local Studio Mode. Start your local LLM backend at `http://localhost:8001/v1` for full autonomous completions)*"
        )
    if "simulate" in lower_inp or "bet" in lower_inp or "impact" in lower_inp:
        return (
            "### ⚡ WYSIWYG Impact Simulation Result\n\n"
            "- **Target Outcome**: O-1 (*Minimize time taken to propagate secrets*)\n"
            "- **Proposed Bet**: Automated Secret Sync Daemon\n"
            "- **Before**: 45 minutes of manual copy-paste across 400 developer pipelines.\n"
            "- **After**: Under 30 seconds ambient zero-touch sync.\n"
            "- **Time-to-Value Shift**: **-90% friction reduction**.\n"
            "- **Human Impact**: 3,000 hours of developer agony eliminated every month. Build it."
        )
    if "evidence" in lower_inp or "call" in lower_inp or "quote" in lower_inp:
        return (
            "### 🔍 Causal Lineage: Real-Time Evidence\n\n"
            "- **Signal Source**: Gong Call #104 (Enterprise Team Alpha)\n"
            "- **Customer Voice**: *'We lost two hours on deploy day because someone missed a database config key.'*\n"
            "- **Telemetry**: 400 microservices impacted weekly; 14% failed build rate attributed to config drift."
        )
    return (
        f'I received your intent: **"{user_input}"**.\n\n'
        "In The Living Studio, every idea is evaluated against human outcomes rather than story points. "
        "Notice how our highest opportunity outcome (`O-1: Minimize propagation time`) has an **Opportunity Score of 15.3**, "
        "signaling severe market underservice. Tap **'Simulate Impact'** on the canvas or type `Simulate Auto-Sync Bet` to test causality."
    )


def _sse(event: str, data: dict[str, Any]) -> str:
    return f"event: {event}\ndata: {json.dumps(data)}\n\n"


def _to_openai_messages(request: ChatRequest) -> list[dict[str, Any]]:
    messages: list[dict[str, Any]] = [{"role": "system", "content": SYSTEM_PROMPT}]
    for message in request.messages:
        messages.append({"role": message.role, "content": message.content})
    return messages


def _openai_tools(mcp_tools: list[Any]) -> list[dict[str, Any]]:
    return [
        {
            "type": "function",
            "function": {
                "name": tool.name,
                "description": tool.description,
                "parameters": tool.input_schema,
            },
        }
        for tool in mcp_tools
    ]


async def stream_chat(request: ChatRequest) -> AsyncIterator[str]:
    """Yield SSE frames: status, delta, tool, message, canvas_dirty."""
    yield _sse("status", {"phase": "health_check"})
    healthy, _message = await check_llm_health(request.base_url, request.api_key, request.model)

    last_user = next((m.content for m in reversed(request.messages) if m.role == "user"), "")

    if not healthy:
        reply = offline_fallback(last_user)
        yield _sse("delta", {"text": reply})
        yield _sse("message", {"content": reply})
        return

    yield _sse("status", {"phase": "mcp_tools"})
    llm_client = AsyncOpenAI(base_url=request.base_url, api_key=request.api_key, timeout=15.0)

    async with McpClient(request.mcp_url) as mcp_client:
        mcp_tools = await mcp_client.list_tools()
        openai_tools = _openai_tools(mcp_tools)
        messages: list[Any] = _to_openai_messages(request)

        yield _sse("status", {"phase": "model"})
        stream: Any = await llm_client.chat.completions.create(  # type: ignore[call-overload]
            model=request.model,
            messages=messages,
            tools=openai_tools if openai_tools else None,
            tool_choice="auto" if openai_tools else None,
            stream=True,
        )

        buffered_text: list[str] = []
        tool_calls: dict[int, dict[str, str]] = {}

        async for chunk in stream:
            delta = chunk.choices[0].delta
            if delta.content:
                buffered_text.append(delta.content)
            for tool_call in delta.tool_calls or []:
                entry = tool_calls.setdefault(
                    tool_call.index, {"id": "", "name": "", "arguments": ""}
                )
                if tool_call.id:
                    entry["id"] = tool_call.id
                if tool_call.function is not None:
                    if tool_call.function.name:
                        entry["name"] = tool_call.function.name
                    if tool_call.function.arguments:
                        entry["arguments"] += tool_call.function.arguments

        if not tool_calls:
            content = "".join(buffered_text)
            if content:
                yield _sse("delta", {"text": content})
            yield _sse("message", {"content": content})
            return

        messages.append(
            {
                "role": "assistant",
                "content": None,
                "tool_calls": [
                    {
                        "id": entry["id"],
                        "type": "function",
                        "function": {
                            "name": entry["name"],
                            "arguments": entry["arguments"] or "{}",
                        },
                    }
                    for entry in tool_calls.values()
                ],
            }
        )

        for entry in tool_calls.values():
            name = entry["name"]
            yield _sse("tool", {"name": name, "status": "start"})
            try:
                arguments = json.loads(entry["arguments"] or "{}")
            except json.JSONDecodeError:
                arguments = {}

            try:
                result = await mcp_client.call_tool(name, arguments)
                result_str = str(result)
                yield _sse("tool", {"name": name, "status": "ok", "preview": result_str[:280]})
            except Exception as exc:  # noqa: BLE001
                result_str = f"Error calling {name}: {exc}"
                yield _sse("tool", {"name": name, "status": "error", "preview": result_str})

            messages.append(
                {
                    "role": "tool",
                    "tool_call_id": entry["id"],
                    "name": name,
                    "content": result_str,
                }
            )

        yield _sse("canvas_dirty", {"value": True})

        final_stream: Any = await llm_client.chat.completions.create(
            model=request.model,
            messages=messages,
            stream=True,
        )
        final_parts: list[str] = []
        async for chunk in final_stream:
            delta = chunk.choices[0].delta
            if delta.content:
                final_parts.append(delta.content)
                yield _sse("delta", {"text": delta.content})

        yield _sse("message", {"content": "".join(final_parts)})


__all__ = ["SYSTEM_PROMPT", "offline_fallback", "stream_chat"]

