<!DOCTYPE html><html><head><meta charset="utf-8"></head><body>
<div id="root"></div>
<script src="/node_modules/react/umd/react.development.js"></script>
<script src="/node_modules/react-dom/umd/react-dom.development.js"></script>
<script>
const e = React.createElement;
function App(){
  const [imp,setImp]=React.useState(8.5);
  const [sat,setSat]=React.useState(3.5);
  return e('div',null,
    e('label',{htmlFor:'i'},'Importance Score (1-10): '+imp.toFixed(1)),
    e('input',{id:'i',type:'range',min:1,max:10,step:0.1,value:imp,onChange:ev=>setImp(Number(ev.target.value))}),
    e('span',{id:'out'},'calc='+(imp+Math.max(imp-sat,0)).toFixed(2))
  );
}
ReactDOM.createRoot(document.getElementById('root')).render(e(App));
</script></body></html>
EOF
cat > run.mjs <<'EOF'
import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage();
await p.goto("http://127.0.0.1:8899/app.html");
const before = await p.locator("#out").textContent();
// Method A: fill()
try {
  await p.locator("#i").fill("9.2");
  await p.waitForTimeout(200);
  console.log("AFTER fill():", await p.locator("#out").textContent(), "| label:", await p.locator("label").textContent());
} catch (e) { console.log("fill() THREW:", e.message.split("\n")[0]); }
// Method B: keyboard
await p.locator("#i").focus();
for (let i=0;i<5;i++) await p.keyboard.press("ArrowRight");
await p.waitForTimeout(200);
console.log("AFTER keys():", await p.locator("#out").textContent(), "| label:", await p.locator("label").textContent());
// Method C: evaluate + native setter
await p.evaluate(()=>{ const el=document.getElementById('i'); const s=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set; s.call(el,'7.7'); el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); });
await p.waitForTimeout(200);
console.log("AFTER native setter:", await p.locator("#out").textContent(), "| label:", await p.locator("label").textContent());
await b.close();
EOF
